"""Two downloaded supplements inspected; exact source sets remain open."""
import json
import ledger as L
from review_batch_0001 import evidence
ROWS=[('10.1021/acs.langmuir.8b02362', '13257158-la8b02362_si_001.docx', '13257158', 'Complete DOCX paragraph/table text; figures not visually inspected', 'SI establishes AFM manipulation of DNA origami on mica, including inside-to-outside manipulation, two-object manipulation, stability after one day and four-week-old samples. Scratch distances44/77/99nm and magnesium/rinse conditions are experimental settings, not independent DNA cores. PMMA scratch calibration is a control. Exact shape, parent design, scaffold/staples and native routing require main/source inspection; extracted captions do not establish complete designs.'), ('10.1021/acsabm.8b00379', '13293500-mt8b00379_si_001.pdf', '13293500', 'All three pages text/captions; images not visually audited', 'SI compares origami on interface and in bulk solution under cooling at minus20/40/60/80C and pH2/12. These are environmental conditions, not separately established DNA designs. Captions support origami reuse but do not provide shape, exact scaffold, staple sets or native source. Main article and parent design remain pending.'), ('10.1021/acs.nanolett.8b02093', '13383521-nl8b02093_si_001.pdf', '13383521', 'SI Notes1–6, Note4 sequence-block headings and Notes7–8 control captions; full sequences/map not audited', 'M13mp18 linearized with PstI is folded into two seven-duplex rods at different scaffold regions. Four component staple blocks specify rod1 for500/1019nt, rod2 for1019/2000nt, rod3 for500/1481nt and rod4 for1481/2000nt constructs. Thus indicated pairs are1+3,1+2,3+4,2+4 respectively; this is an inference from explicit block labels, not a routing audit. Note3 shows a caDNAno plan split across three lines; no native file verified. Note5 gel names all four variants. Note7 927nm dsDNA is a measurement control. Exact scaffold origin/cut indexing, complete staple reconciliation, unpaired lengths and lattice/source eligibility remain open.')]
def main():
 pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 for key,name,fid,loc,note in ROWS:
  e=evidence(L.ROOT/'assets/sources/acs-expansion-20261104'/name,'https://ndownloader.figshare.com/files/'+fid,loc);p=pubs[key]
  if e not in p['evidence']:p['evidence'].append(e)
  p.update(title=p['legacy_record']['publication'],review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',rationale=note,unresolved_questions=['Inspect main article, native/parent sources, exact scaffold and all variant compositions.','Audit complete base and replacement oligo sets against diagrams; resolve narrow catalog eligibility.','Enumerate bibliography and follow backward/forward citations and author routes.'],reviewer='Codex named SI sections and tables',run_id='B0014',date=L.DATE)
  L.upsert('publication_reviews',p,'Record primary supplement design evidence without source-completeness inference')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0014');pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 action='First3of25 inputs inspected: AFM manipulation, environmental stability and two-rod persistence-length supplements; no complete-source certifications.'
 if action not in b['completed_actions']:b['completed_actions'].append(action)
 b.update(after_counts=L.counts(),unresolved_keys=[k for k in b['input_keys'] if pubs[k]['review_stage']=='unreviewed'],validation=[L.validate()],next_queue=['acsami8b12374 and remaining12ACS SI','Ten rotating2015records','All source and discovery followups; FNANO2010'])
 L.upsert('batches',b,'Save3of25first-pass coverage and concrete remaining queue')
 L.atomic(L.HERE/'batch_0014_first_audit.json',json.dumps(dict(reviewed_keys=[r[0] for r in ROWS],first_pass_count=3,input_count=25,validation=L.validate(),counts=L.counts()),indent=2)+'\n');print(L.validate())
if __name__=='__main__':main()
